function assignMockTopics() {
    Object.keys(MOCK_QUESTIONS).forEach(subject => {
        const topics = MOCK_SYLLABUS[subject] || [];
        MOCK_QUESTIONS[subject].forEach((q, i) => {
            q.topic = topics[i % topics.length] || 'General';
        });
    });
}
assignMockTopics();

